import React from 'react';
import {
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Paper,
} from '@mui/material';
import {
  MenuBook,
  VideoLibrary,
  Description,
  GetApp,
  School,
  LocalHospital,
} from '@mui/icons-material';

interface Resource {
  title: string;
  type: string;
  description: string;
  icon: React.ReactNode;
  buttonText: string;
  disabled?: boolean;
}

const ResourcesPage: React.FC = () => {
  const resources: Resource[] = [
    {
      title: 'Insurance Glossary',
      type: 'Glossary',
      description:
        'Understand common insurance terms and jargon. A comprehensive A-Z guide.',
      icon: <MenuBook sx={{ fontSize: 40, color: '#2563eb' }} />,
      buttonText: 'Read More',
      disabled: true,
    },
    {
      title: 'How to Choose Health Insurance',
      type: 'Video',
      description:
        'An explainer video breaking down the key factors to consider when buying a health plan.',
      icon: <VideoLibrary sx={{ fontSize: 40, color: '#2563eb' }} />,
      buttonText: 'Watch Now',
      disabled: true,
    },
    {
      title: 'Top 5 Mistakes to Avoid',
      type: 'Article',
      description:
        'An in-depth article on common pitfalls when purchasing life insurance.',
      icon: <Description sx={{ fontSize: 40, color: '#2563eb' }} />,
      buttonText: 'Read More',
      disabled: true,
    },
    {
      title: 'Financial Planning Template',
      type: 'Template',
      description:
        'Download our Excel template to help you assess your insurance needs and budget.',
      icon: <GetApp sx={{ fontSize: 40, color: '#2563eb' }} />,
      buttonText: 'Download',
      disabled: true,
    },
    {
      title: 'Understanding Deductibles',
      type: 'Article',
      description:
        'Learn how deductibles work and how they impact your premium and out-of-pocket expenses.',
      icon: <School sx={{ fontSize: 40, color: '#2563eb' }} />,
      buttonText: 'Read More',
      disabled: true,
    },
    {
      title: 'Health Insurance Claims Guide',
      type: 'Guide',
      description:
        'Step-by-step guide on how to file and track your health insurance claims successfully.',
      icon: <LocalHospital sx={{ fontSize: 40, color: '#2563eb' }} />,
      buttonText: 'Read More',
      disabled: true,
    },
  ];

  return (
    <Box sx={{ bgcolor: '#f8fafc', minHeight: '100vh', py: 8 }}>
      <Container maxWidth="lg">
        <Typography
          variant="h3"
          component="h1"
          gutterBottom
          align="center"
          sx={{ color: '#1e40af', fontWeight: 700, mb: 2 }}
        >
          Knowledge Center
        </Typography>
        <Typography
          variant="body1"
          align="center"
          sx={{ color: '#64748b', mb: 6, maxWidth: 700, mx: 'auto' }}
        >
          Empower yourself with our curated collection of articles, videos, and
          tools to make informed insurance decisions.
        </Typography>

        <Grid container spacing={4}>
          {resources.map((resource, index) => (
            <Grid item xs={12} sm={6} md={4} key={index}>
              <Card
                sx={{
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  transition: 'all 0.3s ease',
                  '&:hover': {
                    transform: 'translateY(-8px)',
                    boxShadow: 6,
                  },
                }}
              >
                <CardContent
                  sx={{
                    flexGrow: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    textAlign: 'center',
                    p: 3,
                  }}
                >
                  <Paper
                    elevation={0}
                    sx={{
                      bgcolor: '#eff6ff',
                      borderRadius: '50%',
                      width: 80,
                      height: 80,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      mb: 2,
                    }}
                  >
                    {resource.icon}
                  </Paper>

                  <Typography
                    variant="h6"
                    component="h3"
                    gutterBottom
                    sx={{ fontWeight: 600, color: '#1e293b' }}
                  >
                    {resource.title}
                  </Typography>

                  <Typography
                    variant="caption"
                    sx={{
                      color: '#64748b',
                      mb: 1.5,
                      textTransform: 'uppercase',
                      letterSpacing: 0.5,
                    }}
                  >
                    {resource.type}
                  </Typography>

                  <Typography
                    variant="body2"
                    sx={{ color: '#475569', mb: 3, flexGrow: 1 }}
                  >
                    {resource.description}
                  </Typography>

                  <Button
                    variant="outlined"
                    fullWidth
                    disabled={resource.disabled}
                    sx={{
                      mt: 'auto',
                      borderColor: resource.disabled ? '#cbd5e1' : '#2563eb',
                      color: resource.disabled ? '#94a3b8' : '#2563eb',
                      '&:hover': {
                        borderColor: '#1e40af',
                        bgcolor: '#eff6ff',
                      },
                      '&.Mui-disabled': {
                        borderColor: '#e2e8f0',
                        color: '#cbd5e1',
                      },
                    }}
                  >
                    {resource.buttonText}
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Box sx={{ mt: 8, textAlign: 'center' }}>
          <Typography variant="body2" sx={{ color: '#64748b', mb: 2 }}>
            More resources coming soon! Stay tuned for updates.
          </Typography>
        </Box>
      </Container>
    </Box>
  );
};

export default ResourcesPage;
